<script>
 import {normalizeEdit} from '../preview-cache';
 import {Sparkles,ArrowUpRight} from 'lucide-svelte';import {studio,asset,run,updateProject,save,notify,referencePreview,goSettings,importImages,dropImages,current,selectProject,select} from '../studio.svelte';import {api,clone,isTeam} from '../api';import {estimate,money} from '../cost';
 let sourceMode=$state('reference'),prompt=$state(''),modelId=$state(''),resolution=$state('1K'),ratio=$state('1:1'),inputTokens=$state(1300),outputTokens=$state(300),configured=$state(false);
 let models=$derived(studio.catalog?.models||[]),model=$derived(models.find(m=>m.id===modelId)||models[0]);
 $effect(()=>{if(model){if(!modelId)modelId=model.id;if(!model.resolutions.includes(resolution))resolution=model.resolutions[0];if(!model.ratios.includes(ratio))ratio=model.ratios[0];}});
 $effect(()=>{if(studio.mode!=='generate')return;api(model?.id?.startsWith('GPT-Image')?'poe_key_status':'credential_status').then(v=>configured=v).catch(()=>{});});
 let requestContext=$derived(JSON.stringify([studio.dataRoot,studio.pid,studio.aid,sourceMode,asset()?.generatedBase,normalizeEdit(studio.draft),prompt,modelId,resolution,ratio,inputTokens,outputTokens]));
 let cost=$derived(model?estimate(model,resolution,inputTokens,outputTokens):null);
 async function generate(){await run("正在生成",async()=>{
  if(!current()){const project=await api('project_create',{name:'文字生图'});updateProject(project);selectProject(project.id);}
  const context=requestContext;
  if(sourceMode==='reference')await save([studio.aid]);
  if(context!==requestContext)throw Error("请求已更改，请重新点击生成图片。");
  const result=await api('generate',{projectId:studio.pid,assetId:sourceMode==='text'?'':studio.aid,edit:clone(studio.draft),prompt,model:model.id,resolution,ratio,approved:true,estimatedInputTokens:inputTokens,estimatedOutputTokens:outputTokens});
  updateProject(result.project);if(result.assetId&&result.assetId!==studio.aid)select(result.assetId,true);studio.modal={type:'review',version:asset().versions.find(v=>v.id===result.versionId)};notify("图片已生成，请检查结果");
 });}
 async function pasteReference(event){
  if(studio.mode!=='generate'||studio.busy)return;
  const files=[...(event.clipboardData?.files||[])].filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type));if(!files.length)return;
  event.preventDefault();const file=files[0];try{await dropImages([file]);studio.mode='generate';const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');const pasted=current()?.assets.find(a=>a.sha256===hash&&!a.trashed);if(pasted)select(pasted.id,true);sourceMode='reference';}catch(e){studio.error=e.message;}
 }
</script>
<svelte:window onpaste={pasteReference}/>
<div class="workflow-panel generation-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>生成图片</h1><span>{sourceMode==='text'?'纯文本生图':'参考图生图'} · {model?.id?.startsWith('GPT-Image')?'Poe':'Google'}</span></div><div class="generation-layout"><div class="generation-reference"><div class="segmented" role="group" aria-label="生图方式"><button class:active={sourceMode==='reference'} onclick={()=>sourceMode='reference'}>参考图片</button><button class:active={sourceMode==='text'} onclick={()=>sourceMode='text'}>纯文本生图</button></div>{#if sourceMode==='reference'&&asset()}<img src={referencePreview()} alt="参考图片"/><span>{asset()?.name}</span><div class="generation-history">{#each [...(asset()?.versions||[])].filter(v=>v.kind==='generated').reverse() as v}<button class="line-button" onclick={()=>studio.modal={type:'review',version:v}}>{new Date(v.createdAt*1000).toLocaleDateString()}<ArrowUpRight size={13}/></button>{/each}</div>{:else}<p>{sourceMode==='text'?'只发送文字要求，不发送参考图片。':'粘贴图片（Ctrl+V），或导入参考图片。'}</p>{/if}<button class="line-button" onclick={async()=>{await importImages(false);studio.mode='generate';sourceMode='reference';}}>导入 / 更换参考图</button><p class="hint">可直接在此页按 Ctrl+V 粘贴图片。</p></div><div class="generation-form">{#if model?.id?.startsWith('GPT-Image')}<p class="hint">Poe 按点数计费，实际尺寸以生成结果为准。需要固定像素时，请在导出页设置。</p>{/if}<label>生成要求<textarea aria-label="图片生成要求" bind:value={prompt} placeholder="描述你想生成的图片。" rows="6"></textarea></label><label>生图模型<select aria-label="生图模型" bind:value={modelId}>{#each models as m}<option value={m.id}>{m.name}</option>{/each}</select></label><div class="field-grid"><label>生成分辨率<select bind:value={resolution}>{#each model?.resolutions||[] as r}<option>{r}</option>{/each}</select></label><label>宽高比<select bind:value={ratio}>{#each model?.ratios||[] as r}<option>{r}</option>{/each}</select></label></div><details><summary>费用估算参数</summary><div class="field-grid"><label>输入用量估算<input type="number" min="0" bind:value={inputTokens}/></label><label>文字与推理用量估算<input type="number" min="0" bind:value={outputTokens}/></label></div></details><div class="cost-line"><span>预计费用</span><b>{money(cost,studio.currency,studio.exchangeRate)}</b></div><button class="primary full" disabled={!!studio.busy||!prompt.trim()||!configured||(sourceMode==='reference'&&!asset())} onclick={generate}><Sparkles size={16}/>生成图片</button>{#if !configured}<button class="text-button" onclick={()=>goSettings('generate')}>{isTeam?"请联系主机管理员配置 Google API":"前往设置配置 Google API"}<ArrowUpRight size={13}/></button>{/if}</div></div></div>
